<div class="row g-3"><div class="col-xl-4"><div class="card"><div class="card-header"><h3 class="card-title">Novo usuário</h3></div><form method="post" action="/usuarios"><div class="card-body"><div class="mb-3"><label class="form-label">Nome</label><input name="nome" class="form-control" required></div><div class="mb-3"><label class="form-label">Login</label><input name="login" class="form-control" required></div><div class="mb-3"><label class="form-label">E-mail</label><input type="email" name="email" class="form-control"></div><div class="mb-3"><label class="form-label">Perfil</label><select name="perfil_id" class="form-select" required><option value="">Selecione</option><?php foreach($perfis as $p):?><option value="<?=e($p['id'])?>"><?=e($p['nome'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Senha</label><input type="password" name="senha" minlength="8" class="form-control" required></div></div><div class="card-footer"><button class="btn btn-primary">Cadastrar</button></div></form></div></div><div class="col-xl-8"><div class="card"><div class="card-header"><h3 class="card-title">Usuários cadastrados</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Nome</th><th>Login</th><th>Perfil</th><th>E-mail</th><th>Status</th></tr></thead><tbody><?php foreach($usuarios as $u):?><tr><td><?=e($u['nome'])?></td><td><?=e($u['login'])?></td><td><?=e($u['perfil'])?></td><td><?=e($u['email'])?></td><td><span class="badge <?=$u['ativo']?'text-bg-success':'text-bg-secondary'?>"><?=$u['ativo']?'Ativo':'Inativo'?></span></td></tr><?php endforeach;?></tbody></table></div></div></div></div>